) -> PanderaConfig:
    """Gets the configuration context."""
    config = _copy_config(_CONTEXT_CONFIG.get())

    if config.validation_depth is None and validation_depth_default:
        config.validation_depth = validation_depth_default

    return config

for schema_component in schema_components:
    try:
        # Isolate top-level state before disabling coercion below.
        schema_component = copy.copy(schema_component)
        schema_component.__dict__ = schema_component.__dict__.copy()
        if schema.dtype is not None and not isinstance(
            schema.dtype, pandas_engine.PydanticModel
        ):
            # override column dtype with dataframe dtype
            schema_component.dtype = schema.dtype  # type: ignore

        if getattr(schema_component, "parsers", None):
            # coercion of components with parsers is deferred to
            # component-level validation so that parsers run before
            # coercion: propagate dataframe-level coercion.
            schema_component.coerce = (  # type: ignore
                schema_component.coerce or schema.coerce
            )
        else:
            # disable coercion at the schema component level since the
            # dataframe-level schema already coerced it.
            schema_component.coerce = False  # type: ignore

        result = schema_component.validate(
            check_obj, lazy=lazy, inplace=True
        )

        check_passed.append(is_table(result))
        if getattr(
            schema_component, "drop_invalid_rows", False
        ) and is_table(result):
            # The component already dropped its own invalid rows into
            # `result` instead of raising. Mutate check_obj in place
            # so the caller, which shares this same object, sees it.
            dropped = check_obj.index.difference(result.index)
            if len(dropped):
                check_obj.drop(index=dropped, inplace=True)

def strict_filter_columns(
    self, check_obj: pd.DataFrame, schema, column_info: ColumnInfo
):
    """Filters columns that aren't specified in the schema."""
    # dataframe strictness check makes sure all columns in the dataframe
    # are specified in the dataframe schema
    if not (schema.strict or schema.ordered):
        return check_obj

    filter_out_columns = []
    sorted_column_names = iter(column_info.sorted_column_names)
    column_errors = []

    for column in column_info.destuttered_column_names:
        is_schema_col = column in column_info.expanded_column_names
        if schema.strict is True and not is_schema_col:
            column_errors.append(
                SchemaError(
                    schema=schema,
                    data=check_obj,
                    message=(
                        f"column '{column}' not in {schema.__class__.__name__}"
                        f" {schema.columns}"
                    ),
                    failure_cases=column,
                    check="column_in_schema",
                    reason_code=SchemaErrorReason.COLUMN_NOT_IN_SCHEMA,
                )
            )
        if schema.strict == "filter" and not is_schema_col:
            filter_out_columns.append(column)
        if schema.ordered and is_schema_col:
            try:
                next_ordered_col = next(sorted_column_names)
            except StopIteration:
                # Schema column appears again after the ordered run of
                # expected columns (e.g. ... a, b, c, a with schema a, b).
                column_errors.append(
                    SchemaError(
                        schema=schema,
                        data=check_obj,
                        message=f"column '{column}' out-of-order",
                        failure_cases=column,
                        check="column_ordered",
                        reason_code=SchemaErrorReason.COLUMN_NOT_ORDERED,
                    )
                )
            else:
                if next_ordered_col != column:
                    column_errors.append(
                        SchemaError(
                            schema=schema,
                            data=check_obj,
                            message=f"column '{column}' out-of-order",
                            failure_cases=column,
                            check="column_ordered",
                            reason_code=SchemaErrorReason.COLUMN_NOT_ORDERED,
                        )
                    )

    if column_errors:
        raise SchemaErrors(
            schema=schema,
            schema_errors=column_errors,
            data=check_obj,
        )

    if schema.strict == "filter":
        if type(check_obj).__module__.startswith("pyspark.pandas"):
            # NOTE: remove this when we have a separate backend for pyspark
            # pandas.
            check_obj = check_obj.drop(labels=filter_out_columns, axis=1)
        else:
            check_obj.drop(labels=filter_out_columns, inplace=True, axis=1)

    return check_obj

def set_defaults(self, check_obj: pd.DataFrame, schema):
    """Sets default values for missing values."""
    from pandera.backends.pandas.array import ArraySchemaBackend

    assert schema is not None, "The `schema` argument must be provided."

    for col_name, col_schema in schema.columns.items():
        if (
            pd.isna(col_schema.default)
            or col_name not in check_obj.columns
        ):
            continue
        check_obj[col_name] = check_obj[col_name].fillna(
            col_schema.default
        )
        # In pandas >= 3.0, fillna doesn't automatically coerce the dtype
        # when filling an all-null column. Try to convert to the schema's
        # dtype if the column is all non-null after fillna.
        check_obj[col_name] = (
            ArraySchemaBackend._try_convert_dtype_after_fillna(
                check_obj[col_name], col_schema.dtype, col_schema.default
            )
        )

    return check_obj

@validate_scope(scope=ValidationScope.DATA)
def check_column_values_are_unique(
    self, check_obj: pd.DataFrame, schema
) -> CoreCheckResult:
    """Check that column values are unique."""

    passed = True
    message = None
    failure_cases = None

    if not schema.unique:
        return CoreCheckResult(
            passed=passed,
            check="multiple_fields_uniqueness",
        )

    keep_setting = convert_uniquesettings(schema.report_duplicates)
    temp_unique: list[list] = (
        [schema.unique]
        if all(isinstance(x, str) for x in schema.unique)
        else schema.unique
    )
    for lst in temp_unique:
        subset = [x for x in lst if x in check_obj]
        if not subset:
            continue
        duplicates = check_obj.duplicated(  # type: ignore
            subset=subset,
            keep=keep_setting,  # type: ignore
        )
        if duplicates.any():
            # NOTE: this is a hack to support pyspark.pandas, need to
            # figure out a workaround to error: "Cannot combine the
            # series or dataframe because it comes from a different
            # dataframe."
            if type(duplicates).__module__.startswith("pyspark.pandas"):
                import pyspark.pandas as ps

                with ps.option_context("compute.ops_on_diff_frames", True):
                    failure_cases = check_obj.loc[duplicates, subset]
            else:
                failure_cases = check_obj.loc[duplicates, subset]

            passed = False
            message = (
                f"columns '{(*subset,)}' not unique:\n{failure_cases}"
            )
            failure_cases = reshape_failure_cases(failure_cases)
            break
    return CoreCheckResult(
        passed=passed,
        check="multiple_fields_uniqueness",
        reason_code=SchemaErrorReason.DUPLICATES,
        message=message,
        failure_cases=failure_cases,

def subsample(
    self,
    check_obj,
    head: int | None = None,
    tail: int | None = None,
    sample: int | None = None,
    random_state: int | None = None,
):
    pandas_obj_subsample = []
    if head is not None:
        pandas_obj_subsample.append(check_obj.head(head))
    if tail is not None:
        pandas_obj_subsample.append(check_obj.tail(tail))
    if sample is not None:
        pandas_obj_subsample.append(
            check_obj.sample(sample, random_state=random_state)
        )
    return (
        check_obj
        if not pandas_obj_subsample
        else pd.concat(pandas_obj_subsample).pipe(
            lambda x: x[~x.index.duplicated()]
        )
    )

:param args: arguments to pass into check object.
:returns: True if check results pass or check.raise_warning=True, otherwise
    False.
"""
check_result: CheckResult = check(check_obj, *args)

passed = check_result.check_passed
failure_cases = None
message = None

if not passed:
    if check_result.failure_cases is None:
        failure_cases = check_result.check_passed
        message = format_generic_error_message(
            schema, check, check_index
        )
    else:
        failure_cases = reshape_failure_cases(
            check_result.failure_cases, check.ignore_na
        )
        message = format_vectorized_error_message(
            schema, check, check_index, failure_cases
        )

    # raise a warning without exiting if the check is specified to do so
    # but make sure the check passes
    if check.raise_warning:
        warnings.warn(
            message,
            SchemaWarning,
        )
        return CoreCheckResult(
            passed=True,
            check=check,
            reason_code=SchemaErrorReason.DATAFRAME_CHECK,
        )

def drop_invalid_rows(self, check_obj, error_handler: ErrorHandler):
    """Remove invalid elements in a check obj according to failures caught by the error handler."""
    for err in error_handler.schema_errors:
        if isinstance(err.failure_cases, str):
            # if the failure cases are a string, it means the error is
            # a schema-level error.
            continue
        # failure_cases may be a DataFrame (with "index" column) or a Series (use .index)
        if isinstance(err.failure_cases, pd.Series):
            # Series: use .index to get failing row indices
            index_values = err.failure_cases.index
        elif isinstance(check_obj.index, pd.MultiIndex):
            index_tuples = err.failure_cases["index"].apply(eval)
            index_values = pd.MultiIndex.from_tuples(index_tuples)
        else:
            index_values = err.failure_cases["index"]
            # align dtypes so isin() matches (e.g. "1" vs 1)
            try:
                if hasattr(check_obj.index, "dtype") and hasattr(
                    index_values, "astype"
                ):
                    index_values = index_values.astype(
                        check_obj.index.dtype
                    )
            except (TypeError, ValueError):
                pass

        mask = ~check_obj.index.isin(index_values)
        check_obj = check_obj.loc[mask]

    # Restore parsed column values that may have been overwritten (e.g. custom
    # parser + drop_invalid_rows returning None in parsed column, #2216).
    parsed = _parsed_column_values.get()
    if parsed:
        for colname, series in parsed.items():
            if colname not in check_obj.columns:
                continue
            try:
                restored = series.reindex(check_obj.index)
                check_obj.loc[:, colname] = restored.values
            except Exception:
                pass
        _parsed_column_values.set(None)

    return check_obj

def preprocess_field(
    self,
    check_obj,
) -> Union[pd.Series, dict[str, pd.Series]]:
    if self.check.groupby is None:
        if self.check.ignore_na and check_obj.hasnans:
            return check_obj.dropna()
        return check_obj
    return cast(
        dict[str, pd.Series],
        self._format_groupby_input(
            self.groupby(check_obj), self.check.groups
        ),
    )

def preprocess_table_with_key(
    self,
    check_obj,
    key,
) -> Union[pd.DataFrame, dict[str, pd.DataFrame]]:
    if self.check.groupby is None:
        if self.check.ignore_na and check_obj[key].hasnans:
            return check_obj[key].dropna()
        return check_obj[key]
    return cast(
        dict[str, pd.DataFrame],
        self._format_groupby_input(
            self.groupby(check_obj)[key], self.check.groups
        ),
    )

def postprocess_field(
    self,
    check_obj,
    check_output,
) -> CheckResult:
    """Postprocesses the result of applying the check function."""
    if check_output.empty and check_output.dtype != bool:
        check_output = check_output.astype(bool)

    return CheckResult(
        check_output,
        check_output.all(),
        check_obj,
        self._get_series_failure_cases(check_obj, check_output),
    )

def postprocess_table_with_field_output(
    self,
    check_obj,
    check_output,
) -> CheckResult:
    """Postprocesses the result of applying the check function."""
    if check_output.empty and check_output.dtype != bool:
        check_output = check_output.astype(bool)

    if check_obj.index.equals(check_output.index) and self.check.ignore_na:
        check_output = check_output | check_obj.isna().all(axis="columns")
    return CheckResult(
        check_output,
        check_output.all(),
        check_obj,
        self._get_series_failure_cases(check_obj, check_output),
    )

def postprocess_table(
    self,
    check_obj,
    check_output,
) -> CheckResult:
    """Postprocesses the result of applying the check function."""
    assert check_obj.shape == check_output.shape

    for col, dtype in check_output.dtypes.items():
        if check_output[col].empty and dtype != bool:
            check_output[col] = check_output[col].astype(bool)

    if check_obj.index.equals(check_output.index) and self.check.ignore_na:
        check_output = check_output | check_obj.isna()

def validate_scope(scope: ValidationScope):
    """This decorator decides if a function needs to be run or skipped based on params

    :param params: The configuration parameters to which define how pandera has
        to be used
    :param scope: the scope for which the function is valid. i.e. "DATA" scope
        function only works to validate the data values, "SCHEMA"  scope runs for
        checks at the schema/metadata level.
    """

    def _wrapper(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            config = get_config_context()

            if scope == ValidationScope.SCHEMA:
                if config.validation_depth == ValidationDepth.DATA_ONLY:
                    logger.debug(
                        f"Skipping execution of check {func.__name__} since "
                        "validation depth is set to DATA_ONLY.",
                        stacklevel=2,
                    )
                    return CoreCheckResult(passed=True)
                return func(*args, **kwargs)

            elif scope == ValidationScope.DATA:
                if config.validation_depth == ValidationDepth.SCHEMA_ONLY:
                    logger.debug(
                        f"Skipping execution of check {func.__name__} since "
                        "validation depth is set to SCHEMA_ONLY",
                        stacklevel=2,
                    )
                    return CoreCheckResult(passed=True)
                return func(*args, **kwargs)

        return wrapper

    return _wrapper

def main() -> None:
    """Entry point for the ``pandera`` console script and ``python -m pandera``."""
    try:
        import typer  # noqa: F401
    except ImportError as exc:
        sys.stderr.write(
            "The pandera CLI requires typer. Install with:\n"
            "  pip install 'pandera[cli]'\n"
        )
        raise SystemExit(1) from exc
    from pandera._cli import run

    run()

def load_raw_schema(path: Path) -> dict[str, Any]:
    suffix = path.suffix.lower()
    if suffix in (".yaml", ".yml"):
        try:
            import yaml
        except ImportError as exc:
            typer.secho(
                "Reading YAML schemas requires PyYAML. Install with:\n"
                "  pip install 'pandera[io]'",
                err=True,
            )
            raise typer.Exit(1) from exc
        with path.open(encoding="utf-8") as f:
            raw = yaml.safe_load(f)
    elif suffix == ".json":
        with path.open(encoding="utf-8") as f:
            raw = json.load(f)
    else:
        typer.secho(
            f"Unsupported schema extension {suffix!r}. "
            "Use .yaml, .yml, or .json.",
            err=True,
        )
        raise typer.Exit(1)
    if not isinstance(raw, dict):
        typer.secho(
            "Schema file must contain a JSON object at the top level.",
            err=True,
        )
        raise typer.Exit(1)
    return raw

def deserialize_schema(data: dict[str, Any]):
    st = data.get("schema_type")
    if st in (None, "dataframe"):
        from pandera.io.pandas_io import deserialize_schema

        return deserialize_schema(data)
    if st == "polars_dataframe":
        from pandera.io.polars_io import deserialize_schema

        return deserialize_schema(data)
    if st == "pyspark_sql_dataframe":
        from pandera.io.pyspark_sql_io import deserialize_schema

        return deserialize_schema(data)
    if st == "ibis_table":
        from pandera.io.ibis_io import deserialize_schema

        return deserialize_schema(data)
    typer.secho(f"Unsupported schema_type {st!r}.", err=True)
    raise typer.Exit(1)


def load_dataset(path: Path, backend: str):
    """Load on-disk data in a backend-native container."""
    suffix = path.suffix.lower()

    if backend == "pandas":
        import pandas as pd

        if suffix == ".csv":
            return pd.read_csv(path)
        if suffix in (".parquet", ".pq"):
            return pd.read_parquet(path)
        if suffix == ".json":
            return pd.read_json(path)
        if suffix in (".feather", ".ipc"):
            return pd.read_feather(path)
        typer.secho(
            f"Unsupported data extension {suffix!r} for pandas. "
            "Try .csv, .parquet, .json, or .feather.",
            err=True,
        )
        raise typer.Exit(1)
